files.content:
:root {
  --background: #ffffff;
  --foreground: #18181b;
  --card: #ffffff;
  --card-foreground: #18181b;
  --primary: #1d4ed8;
  --primary-foreground: #ffffff;
  --muted: #f4f4f5;
  --muted-foreground: #52525b;
  --border: #71717a;
  --ring: #1d4ed8;
  --destructive: #b91c1c;
  --radius: 8px;
  --font-sans: ui-sans-serif, system-ui, sans-serif;
}

.dark {
  --background: #09090b;
  --foreground: #fafafa;
  --card: #18181b;
  --card-foreground: #fafafa;
  --primary: #60a5fa;
  --primary-foreground: #09090b;
  --muted: #18181b;
  --muted-foreground: #d4d4d8;
  --ring: #60a5fa;
  --destructive: #f87171;
}

[data-afferent-screen] {
  box-sizing: border-box;
  color: var(--foreground);
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.5;
}

[data-afferent-screen] *,
[data-afferent-screen] *::before,
[data-afferent-screen] *::after {
  box-sizing: inherit;
}

[data-afferent-screen] :focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}

.afferent-skip-link {
  left: 16px;
  position: fixed;
  top: 0;
  transform: translateY(-150%);
  z-index: 50;
}

.afferent-skip-link:focus {
  background: var(--background);
  color: var(--foreground);
  padding: 8px 16px;
  transform: translateY(8px);
}

.afferent-board {
  margin-inline: auto;
  max-width: 960px;
  padding: 32px 16px 48px;
}

.afferent-board__header {
  align-items: flex-start;
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  justify-content: space-between;
  margin-bottom: 32px;
}

.afferent-board h1 {
  font-size: 28px;
  font-weight: 600;
  line-height: 1.2;
  margin: 0 0 8px;
}

.afferent-board h2 {
  font-size: 20px;
  font-weight: 600;
  line-height: 1.3;
  margin: 0;
}

.afferent-board p {
  margin: 0;
}

.afferent-button {
  align-items: center;
  background: var(--primary);
  border: 1px solid var(--primary);
  border-radius: var(--radius);
  color: var(--primary-foreground);
  display: inline-flex;
  font: 600 16px/1.5 var(--font-sans);
  gap: 8px;
  justify-content: center;
  min-height: 44px;
  padding: 8px 16px;
}

.afferent-button svg {
  height: 20px;
  width: 20px;
}

.afferent-button--secondary {
  background: var(--background);
  border-color: var(--border);
  color: var(--foreground);
  margin-top: 24px;
}

.afferent-button:disabled {
  opacity: 0.65;
}

.afferent-board__list {
  display: grid;
  gap: 16px;
  list-style: none;
  margin: 0;
  padding: 0;
}

.afferent-feedback-card {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  display: grid;
  gap: 16px;
  padding: 16px;
}

.afferent-feedback-card a {
  color: var(--foreground);
  text-decoration: underline;
  text-underline-offset: 4px;
}

.afferent-feedback-card__content {
  display: grid;
  gap: 8px;
  min-width: 0;
}

.afferent-feedback-card__body {
  max-width: 72ch;
  overflow-wrap: anywhere;
}

.afferent-feedback-card__status {
  color: var(--muted-foreground);
  font-size: 14px;
}

.afferent-feedback-card__totals {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  margin: 0;
}

.afferent-feedback-card__totals div {
  align-items: center;
  display: flex;
  gap: 8px;
}

.afferent-feedback-card__totals dt {
  align-items: center;
  display: flex;
  font-size: 14px;
  font-weight: 600;
  gap: 4px;
}

.afferent-feedback-card__totals dd {
  font-size: 14px;
  margin: 0;
}

.afferent-feedback-card__totals svg {
  height: 16px;
  width: 16px;
}

.afferent-state {
  background: var(--muted);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  display: grid;
  gap: 8px;
  padding: 24px;
}

.afferent-state__action {
  margin-top: 8px;
}

@media (min-width: 640px) {
  .afferent-board {
    padding-inline: 32px;
  }

  .afferent-feedback-card {
    grid-template-columns: minmax(0, 1fr) auto;
    padding: 24px;
  }
}

@media (prefers-reduced-motion: reduce) {
  [data-afferent-screen] *,
  [data-afferent-screen] *::before,
  [data-afferent-screen] *::after {
    animation-duration: 0.01ms !important;
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
  }
}

@media (forced-colors: active) {
  [data-afferent-screen] :focus-visible {
    outline-color: Highlight;
  }
}

"use client";

import { createContext, useContext, useMemo, type ReactNode } from "react";

import {
  mergeAfferentUiCopy,
  type AfferentUiCopy,
