function mergeRecord<T extends object>(base: T, override: DeepPartial<T>): T {
  const result = { ...base } as Record<string, unknown>;
  for (const key of Object.keys(override) as (keyof T)[]) {
    const next = override[key];
    if (next === undefined) continue;
    const current = base[key];
    result[String(key)] =
      typeof current === "object" &&
      current !== null &&
      typeof next === "object" &&
      next !== null
        ? mergeRecord(current, next as DeepPartial<typeof current>)
        : next;
  }
  return result as T;
}

export function mergeAfferentUiCopy(
  override: DeepPartial<AfferentUiCopy> = {},
): AfferentUiCopy {
  return mergeRecord(englishAfferentUiCopy, override);
}

import {
  ArrowUp,
  ChevronRight,
  CircleAlert,
  LoaderCircle,
  MessageSquare,
  Plus,
} from "lucide-react";
import type { ComponentType, SVGProps } from "react";

export type AfferentIcon = ComponentType<SVGProps<SVGSVGElement>>;

export type AfferentIconSlots = Readonly<{
  create: AfferentIcon;
  error: AfferentIcon;
  loading: AfferentIcon;
  comments: AfferentIcon;
  votes: AfferentIcon;
  disclosure: AfferentIcon;
}>;

export const defaultAfferentIcons: AfferentIconSlots = {
  create: Plus,
  error: CircleAlert,
  loading: LoaderCircle,
  comments: MessageSquare,
  votes: ArrowUp,
  disclosure: ChevronRight,
};

import type { AnchorHTMLAttributes, ComponentType, ReactNode } from "react";

export type AfferentHrefBuilder = Readonly<{
  post: (id: string) => string;
  roadmap: (boardId?: string) => string;
  changelog: (slug: string) => string;
}>;

export type AfferentLinkProps = AnchorHTMLAttributes<HTMLAnchorElement> &
  Readonly<{ href: string; children: ReactNode }>;

export type AfferentLinkComponent = ComponentType<AfferentLinkProps>;

export type AfferentNavigation = Readonly<{
  href: AfferentHrefBuilder;
  Link: AfferentLinkComponent;
  navigate?: (href: string) => void;
  currentLocation: string;
}>;

export function NativeAfferentLink(props: AfferentLinkProps) {
  return <a {...props} />;
}

import type { ReactNode } from "react";

import { cn } from "@/components/afferent/core/utils";

export function AfferentStateRegion({
  title,
  children,
  action,
  tone = "neutral",
  className,
}: Readonly<{
  title: string;
  children: ReactNode;
  action?: ReactNode;
  tone?: "neutral" | "error";
  className?: string;
}>) {
  return (
    <section
      className={cn("afferent-state", className)}
      role={tone === "error" ? "alert" : "status"}
      aria-live={tone === "error" ? "assertive" : "polite"}
    >
      <h2>{title}</h2>
      <div>{children}</div>
      {action ? <div className="afferent-state__action">{action}</div> : null}
    </section>
  );
}

export function assertNever(value: never): never {
  throw new Error(`Unhandled Afferent state: ${JSON.stringify(value)}`);
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
